import{_ as s,o as t,c as i,a2 as e}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"数据库索引与事务","description":"从查询路径和业务一致性出发使用索引与事务，避免把性能和正确性留给线上猜测。","frontmatter":{"title":"数据库索引与事务","description":"从查询路径和业务一致性出发使用索引与事务，避免把性能和正确性留给线上猜测。"},"headers":[],"relativePath":"backend/database.md","filePath":"backend/database.md","lastUpdated":1786262003000}'),n={name:"backend/database.md"};function l(p,a,d,h,r,k){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="数据库索引与事务" tabindex="-1">数据库索引与事务 <a class="header-anchor" href="#数据库索引与事务" aria-label="Permalink to &quot;数据库索引与事务&quot;">​</a></h1><p>数据库设计的两个核心问题是：如何快速找到需要的数据，以及一组相关修改如何保持一致。索引解决前者，事务解决后者；两者都应从真实访问模式出发。</p><h2 id="索引服务于具体查询" tabindex="-1">索引服务于具体查询 <a class="header-anchor" href="#索引服务于具体查询" aria-label="Permalink to &quot;索引服务于具体查询&quot;">​</a></h2><p>先写出常见查询的筛选、排序和关联条件，再考虑索引。一个索引并非越多越好：它会占空间，也会增加写入维护成本。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id, title, created_at</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> articles</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> author_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ? </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ?</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>这个查询通常会受益于以 <code>author_id</code>、<code>status</code>、<code>created_at</code> 为顺序的组合索引；实际顺序仍需根据选择性、数据库实现和执行计划验证。</p><h2 id="用执行计划验证假设" tabindex="-1">用执行计划验证假设 <a class="header-anchor" href="#用执行计划验证假设" aria-label="Permalink to &quot;用执行计划验证假设&quot;">​</a></h2><p>查询慢时，不要只凭字段名加索引。检查执行计划、返回行数、扫描方式和排序是否走到了预期路径；同时使用接近生产量级的数据测试。</p><table tabindex="0"><thead><tr><th>症状</th><th>优先检查</th></tr></thead><tbody><tr><td>扫描行数远高于返回行数</td><td>筛选条件与索引前缀是否匹配</td></tr><tr><td>排序耗时明显</td><td>排序字段是否能被索引顺序利用</td></tr><tr><td>分页越往后越慢</td><td>是否使用过大的 offset，能否改为游标分页</td></tr><tr><td>单条查询很快但列表很慢</td><td>是否存在 N+1 查询或取了过多列</td></tr></tbody></table><h2 id="事务保护一个完整业务动作" tabindex="-1">事务保护一个完整业务动作 <a class="header-anchor" href="#事务保护一个完整业务动作" aria-label="Permalink to &quot;事务保护一个完整业务动作&quot;">​</a></h2><p>转账、扣减库存、创建订单等操作往往涉及多次写入。事务让这些写入在成功时一起提交，发生异常时一起回滚。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开始事务</span></span>
<span class="line"><span>  → 校验库存仍可用</span></span>
<span class="line"><span>  → 创建订单</span></span>
<span class="line"><span>  → 扣减库存</span></span>
<span class="line"><span>提交事务</span></span></code></pre></div><p>事务内尽量短：不要等待用户输入、远程接口或长时间计算。并发写入时，还需考虑隔离级别、唯一约束、版本字段和死锁重试策略。</p><h2 id="数据层检查表" tabindex="-1">数据层检查表 <a class="header-anchor" href="#数据层检查表" aria-label="Permalink to &quot;数据层检查表&quot;">​</a></h2><ul><li>查询只取当前页面真正需要的列。</li><li>关键唯一性由数据库约束兜底，不只依赖应用层判断。</li><li>事务边界与业务承诺一致，失败路径明确。</li><li>变更索引和表结构前，评估读写影响与回滚方案。</li></ul><p>数据库不是“最后一层存储”，它也是业务正确性的重要防线。</p>`,16)])])}const E=s(n,[["render",l]]);export{c as __pageData,E as default};
